declarations.original_declaration:
abstract thing BiologicalMembrane
    "An identified biological membrane separating specified material compartments."
    is physical:MaterialBody;

process CellularRespiration
    "Cellular release of usable energy through respiratory biochemical reactions."
    is biology:Metabolism;

process CellDifferentiation
    "Development in which a cell acquires specialized structural or functional features."
    is biology:Development;

functional directed relationship SignalsTo
    "A biological individual transmits a signal to another biological individual."
    links life:Individual to life:Individual;

structural bond CellAdhesion
    "Two structurally observed cellular bodies are physically adherent."
    links life:CellularBody to life:CellularBody;
